-- Tap Am database (Cloudflare D1). Money is always stored in kobo (₦1 = 100 kobo).
PRAGMA foreign_keys=ON;

-- ── people ──────────────────────────────────────────────────────────────────
-- role: USER | SPONSOR | ADMIN      tier (USER only): LAPO (free) | MAPO (paid) | NEPO (premium)
-- status: ACTIVE | SUSPENDED | ARCHIVED
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, email TEXT UNIQUE COLLATE NOCASE,
  password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, password_iter INTEGER NOT NULL DEFAULT 10000,
  role TEXT NOT NULL DEFAULT 'USER', tier TEXT NOT NULL DEFAULT 'LAPO', tier_until TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE',
  lifetime_taps INTEGER NOT NULL DEFAULT 0, games_played INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, rank_level INTEGER NOT NULL DEFAULT 1,
  referral_code TEXT UNIQUE, referred_by TEXT, referral_count INTEGER NOT NULL DEFAULT 0,
  equipped_skin TEXT NOT NULL DEFAULT 'skin-boy', prefs TEXT NOT NULL DEFAULT '{}',
  date_of_birth TEXT, terms_accepted_at TEXT, terms_version TEXT, email_verified_at TEXT,
  gender TEXT, country TEXT, archived_at TEXT, adult_confirmed_at TEXT, emoji TEXT, emoji_meaning TEXT,
  email_news INTEGER NOT NULL DEFAULT 0, hide_profile INTEGER NOT NULL DEFAULT 0, seed_hash TEXT, seed_salt TEXT, seed_enc TEXT, seed_set_at TEXT, last_free_box_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sponsor_profiles (user_id TEXT PRIMARY KEY, company TEXT NOT NULL, website TEXT, logo_url TEXT, lead_capture INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, text TEXT NOT NULL, link TEXT, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);

-- ── ranks (1..100, generated by the app on first use, editable by the super admin) ──
CREATE TABLE IF NOT EXISTS ranks (level INTEGER PRIMARY KEY, name TEXT NOT NULL, min_taps INTEGER NOT NULL DEFAULT 0, min_games INTEGER NOT NULL DEFAULT 0, min_wins INTEGER NOT NULL DEFAULT 0, unlocks TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '#00ff6e');

-- ── pools ───────────────────────────────────────────────────────────────────
-- kind: FREE | PAID | SPONSORED      audience: ALL | LAPO | NEPO      tie_rule: FIRST | SPLIT
CREATE TABLE IF NOT EXISTS pools (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', starts_at TEXT NOT NULL, ends_at TEXT NOT NULL,
  entry_fee INTEGER NOT NULL DEFAULT 0, min_tier TEXT NOT NULL DEFAULT 'LAPO', boosters_allowed INTEGER NOT NULL DEFAULT 1, max_players INTEGER NOT NULL DEFAULT 1000,
  status TEXT NOT NULL DEFAULT 'SCHEDULED', created_by TEXT, hashtag TEXT UNIQUE,
  kind TEXT NOT NULL DEFAULT 'FREE', audience TEXT NOT NULL DEFAULT 'ALL', entry_fee_kobo INTEGER NOT NULL DEFAULT 0, prize_kobo INTEGER NOT NULL DEFAULT 0,
  winners_count INTEGER NOT NULL DEFAULT 1, split TEXT NOT NULL DEFAULT '[100]', tie_rule TEXT NOT NULL DEFAULT 'FIRST', house_cut_pct INTEGER NOT NULL DEFAULT 0,
  is_private INTEGER NOT NULL DEFAULT 0, join_password TEXT, sponsor_user_id TEXT, sponsor_name TEXT,
  theme_color TEXT, skin_url TEXT, game_type TEXT NOT NULL DEFAULT 'STANDARD', side_a TEXT, side_b TEXT,
  promo_id TEXT, bg_color TEXT, split_style TEXT NOT NULL DEFAULT 'TOP', vs_split INTEGER NOT NULL DEFAULT 0, pad_pattern TEXT, allow_own_pad INTEGER NOT NULL DEFAULT 0, lapo_rules INTEGER NOT NULL DEFAULT 0, paused_players TEXT,
  settled_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pool_entries (
  pool_id TEXT NOT NULL, user_id TEXT NOT NULL, taps INTEGER NOT NULL DEFAULT 0, raw_taps INTEGER NOT NULL DEFAULT 0, joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_batch_at TEXT, settled_raw_taps INTEGER NOT NULL DEFAULT 0, side_choice TEXT, booster_item TEXT, reached_at TEXT,
  final_rank INTEGER, prize_kobo INTEGER NOT NULL DEFAULT 0, paid_kobo INTEGER NOT NULL DEFAULT 0, boosters_used INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(pool_id,user_id), FOREIGN KEY(pool_id) REFERENCES pools(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);

-- ── money ───────────────────────────────────────────────────────────────────
-- balance_kobo = wallet (money you add; spend-only)   winnings_kobo = withdrawable
CREATE TABLE IF NOT EXISTS wallets (user_id TEXT PRIMARY KEY, balance_kobo INTEGER NOT NULL DEFAULT 0, winnings_kobo INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS wallet_transactions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, type TEXT NOT NULL, amount_kobo INTEGER NOT NULL, reference TEXT, status TEXT NOT NULL DEFAULT 'SUCCESS', balance TEXT NOT NULL DEFAULT 'WALLET', note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payments (reference TEXT PRIMARY KEY, user_id TEXT NOT NULL, purpose TEXT NOT NULL, amount_kobo INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', provider TEXT NOT NULL DEFAULT 'paystack', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, verified_at TEXT);
CREATE TABLE IF NOT EXISTS withdrawals (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, amount_kobo INTEGER NOT NULL, bank_name TEXT, bank_code TEXT NOT NULL, account_number TEXT NOT NULL, account_name TEXT, status TEXT NOT NULL DEFAULT 'PENDING', transfer_code TEXT, admin_note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT);

-- ── store ───────────────────────────────────────────────────────────────────
-- kind: BOOSTER | SKIN (SHAPE retired)   audience: ALL | MAPO (Mapo + Nepo) | NEPO   per_game_limit: 0 = no limit
CREATE TABLE IF NOT EXISTS store_items (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'BOOSTER', price_kobo INTEGER NOT NULL DEFAULT 0, multiplier REAL NOT NULL DEFAULT 1, duration_seconds INTEGER NOT NULL DEFAULT 30, active INTEGER NOT NULL DEFAULT 1, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  audience TEXT NOT NULL DEFAULT 'ALL', min_rank INTEGER NOT NULL DEFAULT 1, config TEXT NOT NULL DEFAULT '{}', giftable INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, per_game_limit INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory (user_id TEXT NOT NULL, item_id TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 0, acquired_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,item_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(item_id) REFERENCES store_items(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS gifts (id TEXT PRIMARY KEY, from_user_id TEXT, to_user_id TEXT NOT NULL, item_id TEXT NOT NULL, quantity INTEGER NOT NULL, note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

-- ── sponsors' ads ───────────────────────────────────────────────────────────
-- kind: IMAGE | YOUTUBE     (placement is always ALL: before the game, in the lobby and before results)
CREATE TABLE IF NOT EXISTS promos (id TEXT PRIMARY KEY, title TEXT NOT NULL, owner_id TEXT, kind TEXT NOT NULL DEFAULT 'IMAGE', image_url TEXT, video_id TEXT, target_url TEXT, placement TEXT NOT NULL DEFAULT 'ALL', pool_id TEXT, active INTEGER NOT NULL DEFAULT 1, approved INTEGER NOT NULL DEFAULT 0, views INTEGER NOT NULL DEFAULT 0, clicks INTEGER NOT NULL DEFAULT 0, duration_seconds INTEGER NOT NULL DEFAULT 5, reject_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS media (key TEXT PRIMARY KEY, owner_id TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

-- ── voice ───────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS voice_sessions (user_id TEXT PRIMARY KEY, pool_id TEXT NOT NULL, session_id TEXT NOT NULL, track_name TEXT, mode TEXT NOT NULL DEFAULT 'LISTEN', updated_at TEXT NOT NULL);

-- ── misc ────────────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS suggestions (id TEXT PRIMARY KEY, user_id TEXT, name TEXT, email TEXT, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'NEW', kind TEXT NOT NULL DEFAULT 'GENERAL', data TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS slides (id TEXT PRIMARY KEY, title TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', image_url TEXT, link TEXT, color TEXT NOT NULL DEFAULT '#2E8BFF',
  promo_id TEXT, sponsor_id TEXT, status TEXT NOT NULL DEFAULT 'REQUESTED', sort INTEGER NOT NULL DEFAULT 0, note TEXT, views INTEGER NOT NULL DEFAULT 0, clicks INTEGER NOT NULL DEFAULT 0, cta TEXT,
  created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, promo_id TEXT NOT NULL, sponsor_id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, email TEXT, phone TEXT,
  consent_text TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(promo_id, user_id));
CREATE TABLE IF NOT EXISTS backgrounds (id TEXT PRIMARY KEY, name TEXT NOT NULL, style TEXT NOT NULL DEFAULT 'LINEAR', color_a TEXT NOT NULL, color_b TEXT NOT NULL, image_url TEXT,
  active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tap_stats (period TEXT NOT NULL, user_id TEXT NOT NULL, taps INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(period, user_id));
CREATE TABLE IF NOT EXISTS badges (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL, period TEXT NOT NULL, taps INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(kind, period));
CREATE TABLE IF NOT EXISTS metrics (key TEXT NOT NULL, day TEXT NOT NULL, n INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(key, day));
CREATE TABLE IF NOT EXISTS alerts (key TEXT PRIMARY KEY, level TEXT NOT NULL, message TEXT NOT NULL, first_at TEXT NOT NULL, last_at TEXT NOT NULL, emailed_at TEXT, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS ads (id TEXT PRIMARY KEY, slot TEXT NOT NULL UNIQUE, title TEXT NOT NULL, image_url TEXT, target_url TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, admin_user_id TEXT, action TEXT NOT NULL, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_codes (purpose TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE, code_hash TEXT NOT NULL, nonce TEXT NOT NULL, payload TEXT, attempts INTEGER NOT NULL DEFAULT 0, sends INTEGER NOT NULL DEFAULT 1, last_sent_at TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(purpose,email));
CREATE TABLE IF NOT EXISTS auth_throttle (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visitors (vid TEXT PRIMARY KEY, first_seen TEXT NOT NULL, last_seen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS merch (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', price_kobo INTEGER NOT NULL DEFAULT 0, image_url TEXT, color TEXT NOT NULL DEFAULT '#2E8BFF', link TEXT, status TEXT NOT NULL DEFAULT 'SOON', active INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- Special badges made by the super admin. Given badges live in `badges` with kind 'X:<id>' and period = user id.
CREATE TABLE IF NOT EXISTS special_badges (id TEXT PRIMARY KEY, name TEXT NOT NULL, meaning TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '#9161FF', label TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pool_topups (id TEXT PRIMARY KEY, pool_id TEXT NOT NULL, user_id TEXT NOT NULL, amount_kobo INTEGER NOT NULL, balance TEXT NOT NULL DEFAULT 'WALLET', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL, ip TEXT, ua TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS promo_codes (code TEXT PRIMARY KEY, tier TEXT NOT NULL, days INTEGER NOT NULL, max_uses INTEGER NOT NULL DEFAULT 1, used INTEGER NOT NULL DEFAULT 0, expires_at TEXT, active INTEGER NOT NULL DEFAULT 1, note TEXT, created_by TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS promo_redemptions (code TEXT NOT NULL, user_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(code, user_id));
CREATE TABLE IF NOT EXISTS email_blasts (id TEXT PRIMARY KEY, pool_id TEXT NOT NULL, sponsor_id TEXT NOT NULL, audience TEXT NOT NULL DEFAULT 'ALL', price_kobo INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'QUEUED', sent INTEGER NOT NULL DEFAULT 0, cursor TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, done_at TEXT);
CREATE TABLE IF NOT EXISTS merch_interest (email TEXT NOT NULL COLLATE NOCASE, item TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(email,item));

CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_pool_entries_user ON pool_entries(user_id);
CREATE INDEX IF NOT EXISTS idx_pool_entries_score ON pool_entries(pool_id,taps DESC);
CREATE INDEX IF NOT EXISTS idx_pools_dates ON pools(starts_at,ends_at);
CREATE INDEX IF NOT EXISTS idx_visitors_seen ON visitors(last_seen);
CREATE INDEX IF NOT EXISTS idx_wtx_user ON wallet_transactions(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_tap_stats_user ON tap_stats(user_id, period);
CREATE INDEX IF NOT EXISTS idx_topups_pool ON pool_topups(pool_id);
CREATE INDEX IF NOT EXISTS idx_auth_events_user ON auth_events(user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_users_username_search ON users(username);
CREATE INDEX IF NOT EXISTS idx_entries_prize ON pool_entries(prize_kobo);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,read);
CREATE INDEX IF NOT EXISTS idx_promos_active ON promos(active,approved);
CREATE INDEX IF NOT EXISTS idx_slides_status ON slides(status, sort);
CREATE INDEX IF NOT EXISTS idx_leads_sponsor ON leads(sponsor_id, created_at);
CREATE INDEX IF NOT EXISTS idx_tap_stats_board ON tap_stats(period, taps DESC);
CREATE INDEX IF NOT EXISTS idx_badges_user ON badges(user_id);
CREATE INDEX IF NOT EXISTS idx_withdrawals_user ON withdrawals(user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_pools_creator ON pools(created_by);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_referral ON users(referral_code);

